CREATE TABLE IF NOT EXISTS schema_migrations (version INT PRIMARY KEY, applied_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS users (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, phone VARCHAR(30) NOT NULL DEFAULT '', password VARCHAR(100) NOT NULL,
 google_sub VARCHAR(255) NULL UNIQUE, google_email VARCHAR(190) NULL, password_login_enabled BOOLEAN NOT NULL DEFAULT TRUE, phone_verified BOOLEAN NOT NULL DEFAULT FALSE, phone_verification_method VARCHAR(20) NULL, phone_verified_at DATETIME NULL,
 role ENUM('admin','sales','customer') NOT NULL DEFAULT 'customer', active BOOLEAN NOT NULL DEFAULT TRUE, session_version INT NOT NULL DEFAULT 1, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
 INDEX idx_users_role_active(role,active)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS categories (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE, description TEXT NOT NULL, image VARCHAR(255) NOT NULL DEFAULT '', active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS products (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL, description TEXT NOT NULL, price DECIMAL(10,2) NOT NULL, sale_price DECIMAL(10,2) NULL, unit VARCHAR(40) NOT NULL DEFAULT 'packet', stock INT NOT NULL DEFAULT 0,
 category_id INT UNSIGNED NULL, images JSON NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, featured BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL, CHECK(stock>=0), CHECK(price>=0), CHECK(sale_price IS NULL OR (sale_price>=0 AND sale_price<=price)), INDEX idx_products_catalog(active,category_id), INDEX idx_products_featured(active,featured)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS settings (id INT PRIMARY KEY, content JSON NOT NULL, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS carts (user_id INT UNSIGNED PRIMARY KEY, items JSON NOT NULL, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS orders (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NOT NULL, address JSON NOT NULL, subtotal DECIMAL(12,2) NOT NULL, delivery_charge DECIMAL(10,2) NOT NULL DEFAULT 0, total DECIMAL(12,2) NOT NULL,
 status VARCHAR(30) NOT NULL DEFAULT 'Pending', payment_method VARCHAR(20) NOT NULL DEFAULT 'cod', payment_status VARCHAR(30) NOT NULL DEFAULT 'cod', gateway_order_id VARCHAR(100) NULL UNIQUE, gateway_payment_id VARCHAR(100) NULL UNIQUE,
 idempotency_key VARCHAR(100) NULL, checkout_hash CHAR(64) NULL, stock_restored BOOLEAN NOT NULL DEFAULT FALSE, tracking VARCHAR(150) NOT NULL DEFAULT '', delivery_notes TEXT NOT NULL,
 latitude DECIMAL(10,7) NULL, longitude DECIMAL(10,7) NULL, driver_lat DECIMAL(10,7) NULL, driver_lng DECIMAL(10,7) NULL, driver_source VARCHAR(20) NULL, driver_updated_at DATETIME NULL,
 created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 FOREIGN KEY(user_id) REFERENCES users(id), UNIQUE KEY unique_checkout(user_id,idempotency_key), INDEX idx_orders_owner(user_id,id), INDEX idx_orders_status(status,created_at), INDEX idx_orders_created(created_at)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS order_items (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id INT UNSIGNED NOT NULL, product_id INT UNSIGNED NOT NULL, name VARCHAR(150) NOT NULL, quantity INT UNSIGNED NOT NULL, price DECIMAL(10,2) NOT NULL, unit VARCHAR(40) NOT NULL, image VARCHAR(255) NOT NULL DEFAULT '',
 FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(product_id) REFERENCES products(id), UNIQUE KEY unique_order_product(order_id,product_id), CHECK(quantity>0)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS order_activity (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id INT UNSIGNED NOT NULL, actor INT UNSIGNED NULL, status VARCHAR(30) NOT NULL, detail VARCHAR(500) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(actor) REFERENCES users(id), INDEX idx_order_activity(order_id,id)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS leads (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(190) NOT NULL, phone VARCHAR(30) NOT NULL, product VARCHAR(150) NOT NULL, quantity INT UNSIGNED NOT NULL, message TEXT NOT NULL,
 status ENUM('New','Contacted','Converted','Lost') NOT NULL DEFAULT 'New', followup DATE NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 INDEX idx_leads_status(status,created_at), INDEX idx_leads_followup(followup,status)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS lead_notes (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, lead_id INT UNSIGNED NOT NULL, actor INT UNSIGNED NOT NULL, note TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY(lead_id) REFERENCES leads(id), FOREIGN KEY(actor) REFERENCES users(id), INDEX idx_lead_notes(lead_id,id)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS audit_log (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, actor INT UNSIGNED NULL, action VARCHAR(80) NOT NULL, entity_type VARCHAR(40) NOT NULL, entity_id VARCHAR(100) NULL, detail JSON NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY(actor) REFERENCES users(id), INDEX idx_audit_created(created_at), INDEX idx_audit_actor(actor,id)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS payment_events (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, event_id VARCHAR(150) NOT NULL UNIQUE, payment_id VARCHAR(100) NULL, order_id INT UNSIGNED NULL, event_type VARCHAR(50) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY(order_id) REFERENCES orders(id), INDEX idx_payment_order(order_id)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS notifications (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, event_key VARCHAR(150) NOT NULL, channel ENUM('email','sms') NOT NULL, delivery_mode VARCHAR(20) NOT NULL DEFAULT 'simulated', recipient VARCHAR(190) NOT NULL, subject VARCHAR(200) NOT NULL, body TEXT NOT NULL, order_id INT UNSIGNED NULL, lead_id INT UNSIGNED NULL,
 status VARCHAR(30) NOT NULL DEFAULT 'pending', attempts INT NOT NULL DEFAULT 0, lease_until DATETIME NULL, error VARCHAR(500) NULL, provider_id VARCHAR(190) NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, sent_at DATETIME NULL,
 FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(lead_id) REFERENCES leads(id), UNIQUE KEY unique_notification(event_key,channel), INDEX idx_notification_status(status,id), INDEX idx_notification_order(order_id,id)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS uploads (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, filename VARCHAR(100) NOT NULL UNIQUE, original_name VARCHAR(200) NOT NULL, url VARCHAR(255) NOT NULL UNIQUE, size_bytes INT UNSIGNED NOT NULL, width INT UNSIGNED NOT NULL, height INT UNSIGNED NOT NULL, actor INT UNSIGNED NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY(actor) REFERENCES users(id)
) ENGINE=InnoDB;
INSERT IGNORE INTO schema_migrations(version) VALUES(2);

CREATE TABLE IF NOT EXISTS google_challenges (
 id CHAR(36) PRIMARY KEY, nonce_hash CHAR(64) NOT NULL, csrf_hash CHAR(64) NOT NULL, purpose ENUM('signin','link') NOT NULL, user_id INT UNSIGNED NULL, attempts INT NOT NULL DEFAULT 0, expires_at DATETIME NOT NULL, consumed_at DATETIME NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY(user_id) REFERENCES users(id), INDEX idx_google_challenges_expiry(expires_at)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS phone_verifications (
 id CHAR(36) PRIMARY KEY, user_id INT UNSIGNED NOT NULL, phone VARCHAR(30) NOT NULL, phone_snapshot VARCHAR(30) NOT NULL, code_hash CHAR(64) NOT NULL, mode ENUM('simulated','twilio') NOT NULL,
 attempts INT NOT NULL DEFAULT 0, expires_at DATETIME NOT NULL, consumed_at DATETIME NULL, delivery_status VARCHAR(20) NOT NULL DEFAULT 'pending', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY(user_id) REFERENCES users(id), INDEX idx_phone_verifications_user(user_id,created_at), INDEX idx_phone_verifications_expiry(expires_at)
) ENGINE=InnoDB;
INSERT IGNORE INTO schema_migrations(version) VALUES(3);

INSERT IGNORE INTO schema_migrations(version) VALUES(4);

CREATE TABLE IF NOT EXISTS account_addresses (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NOT NULL,
 label VARCHAR(40) NOT NULL DEFAULT 'Home', name VARCHAR(100) NOT NULL, phone VARCHAR(30) NOT NULL,
 flat VARCHAR(100) NOT NULL DEFAULT '', building VARCHAR(150) NOT NULL DEFAULT '', area VARCHAR(150) NOT NULL DEFAULT '', landmark VARCHAR(200) NOT NULL DEFAULT '',
 line1 VARCHAR(500) NOT NULL, line2 VARCHAR(250) NOT NULL DEFAULT '', city VARCHAR(100) NOT NULL, state VARCHAR(100) NOT NULL DEFAULT '', pincode CHAR(6) NOT NULL, country VARCHAR(80) NOT NULL DEFAULT 'India',
 lat DECIMAL(10,7) NULL, lng DECIMAL(10,7) NULL, accuracy DECIMAL(12,2) NULL,
 is_default BOOLEAN NOT NULL DEFAULT FALSE,
 default_owner INT UNSIGNED GENERATED ALWAYS AS (CASE WHEN is_default THEN user_id ELSE NULL END) STORED,
 created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT, UNIQUE KEY unique_default_address(default_owner), INDEX idx_addresses_owner(user_id,id),
 CHECK ((lat IS NULL AND lng IS NULL) OR (lat IS NOT NULL AND lng IS NOT NULL AND lat BETWEEN -90 AND 90 AND lng BETWEEN -180 AND 180))
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS catalogue_state (
 id TINYINT UNSIGNED PRIMARY KEY, revision BIGINT UNSIGNED NOT NULL DEFAULT 0
) ENGINE=InnoDB;
INSERT IGNORE INTO catalogue_state(id,revision) VALUES(1,0);
CREATE TABLE IF NOT EXISTS realtime_events (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, event_name VARCHAR(60) NOT NULL, rooms JSON NOT NULL, payload JSON NOT NULL,
 created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, published_at DATETIME NULL,
 INDEX idx_realtime_pending(published_at,id)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS in_app_notifications (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NOT NULL, audience ENUM('customer','admin') NOT NULL,
 event_key VARCHAR(150) NOT NULL, type VARCHAR(50) NOT NULL, title VARCHAR(150) NOT NULL, body VARCHAR(1000) NOT NULL, order_id INT UNSIGNED NULL, product_id INT UNSIGNED NULL,
 read_at DATETIME NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE SET NULL,
 UNIQUE KEY unique_in_app_event(user_id,audience,event_key), INDEX idx_in_app_owner(user_id,audience,id), INDEX idx_in_app_unread(user_id,audience,read_at,id)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS password_reset_tokens (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 user_id INT UNSIGNED NOT NULL,
 token_hash CHAR(64) NOT NULL UNIQUE,
 expires_at DATETIME NOT NULL,
 consumed_at DATETIME NULL,
 created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY(user_id) REFERENCES users(id), INDEX idx_password_reset_user(user_id,created_at)
) ENGINE=InnoDB;
